const optionNames={a:'Concierge pilot',b:'Focused self-serve MVP',c:'Platform foundation'};
const challenge=document.querySelector('#challenge');
const confidence=document.querySelector('#confidence');
const buttons=[...document.querySelectorAll('[data-option]')];
let lastState={};
function render(state){
  lastState=state;
  challenge.value=state.challenge||'';
  confidence.value=Number(state.confidence??0);
  document.querySelector('#char-count').textContent=challenge.value.length+' / 220';
  const selected=state.selectedOption||'';
  buttons.forEach(button=>button.setAttribute('aria-checked',String(button.dataset.option===selected)));
  document.querySelector('#selection-note').textContent=selected?'Selected · '+optionNames[selected]:'Select one option';
  const value=Number(state.confidence??0);
  document.querySelector('#confidence-value').textContent=value+'%';
  document.querySelector('#confidence-label').textContent=value<45?'The question needs work':value<75?'Clear enough to compare':'Strong shared understanding';
}
buttons.forEach(button=>button.addEventListener('click',()=>window.buildParty.setState('selectedOption',button.dataset.option)));
challenge.addEventListener('input',()=>{document.querySelector('#char-count').textContent=challenge.value.length+' / 220';window.buildParty.setState('challenge',challenge.value)});
confidence.addEventListener('input',()=>window.buildParty.setState('confidence',Number(confidence.value)));
window.buildParty.subscribe(render);
render(window.buildParty.getState());

const criteria=['learning','customer','effort','leverage'];
const options=['a','b','c'];
const names={a:'Concierge pilot',b:'Focused self-serve MVP',c:'Platform foundation'};
const clamp=value=>Math.max(1,Math.min(5,Number(value)||1));
function totals(state){
  const weights=state.weights||{};
  const scores=state.scores||{};
  const weightSum=criteria.reduce((sum,key)=>sum+clamp(weights[key]),0);
  return Object.fromEntries(options.map(option=>[option,Math.round(criteria.reduce((sum,key)=>sum+clamp(weights[key])*clamp((scores[option]||{})[key]),0)/(weightSum*5)*100)]));
}
function render(state){
  criteria.forEach(key=>{
    const weight=clamp((state.weights||{})[key]);
    document.querySelector('[data-weight='+key+']').value=weight;
    document.querySelector('#weight-'+key+'-output').textContent=weight;
    options.forEach(option=>document.querySelector('[data-score-option='+option+'][data-score-criterion='+key+']').value=clamp(((state.scores||{})[option]||{})[key]));
  });
  const result=totals(state);
  const best=Math.max(...Object.values(result));
  const leaders=options.filter(option=>result[option]===best);
  options.forEach(option=>{
    document.querySelector('#total-'+option).textContent=result[option];
    document.querySelector('#bar-'+option).style.width=result[option]+'%';
    document.querySelector('[data-result='+option+']').classList.toggle('leading',leaders.includes(option));
  });
  document.querySelector('#insight-copy').textContent=leaders.length===1?names[leaders[0]]+' leads at '+best+' — inspect the highest-weight trade-offs.':'The current score is tied — discuss where the assumptions differ.';
}
document.querySelectorAll('[data-weight]').forEach(input=>input.addEventListener('input',()=>{
  const state=window.buildParty.getState();
  window.buildParty.patchState({weights:{...(state.weights||{}),[input.dataset.weight]:clamp(input.value)}});
}));
document.querySelectorAll('[data-score-option]').forEach(input=>input.addEventListener('change',()=>{
  const state=window.buildParty.getState();
  const option=input.dataset.scoreOption;
  window.buildParty.patchState({scores:{...(state.scores||{}),[option]:{...((state.scores||{})[option]||{}),[input.dataset.scoreCriterion]:clamp(input.value)}}});
}));
window.buildParty.subscribe(render);
render(window.buildParty.getState());

const names={a:'Concierge pilot',b:'Focused self-serve MVP',c:'Platform foundation'};
const modes={explore:{verb:'Explore',detail:'Gather one more targeted signal before committing resources.'},pilot:{verb:'Pilot',detail:'Run a six-week pilot with explicit learning gates.'},commit:{verb:'Commit to',detail:'Fund the path, name an owner, and set a delivery checkpoint.'}};
const titleCase=value=>value.charAt(0).toUpperCase()+value.slice(1);
function getOutcome(state){
  const votes=state.votes||{};
  const best=Math.max(Number(votes.a)||0,Number(votes.b)||0,Number(votes.c)||0);
  const leaders=['a','b','c'].filter(option=>(Number(votes[option])||0)===best);
  const winner=leaders.length===1?leaders[0]:'b';
  const mode=modes[state.mode]||modes.pilot;
  return {winner,leaders,best,mode,recommendation:mode.verb+' Option '+winner.toUpperCase()};
}
function render(state){
  const votes=state.votes||{};
  const outcome=getOutcome(state);
  const total=['a','b','c'].reduce((sum,option)=>sum+(Number(votes[option])||0),0);
  document.querySelector('#total-votes').textContent=total;
  ['a','b','c'].forEach(option=>{document.querySelector('#votes-'+option).textContent=Number(votes[option])||0;document.querySelector('[data-vote='+option+']').classList.toggle('leader',outcome.leaders.length===1&&outcome.winner===option)});
  document.querySelectorAll('[data-mode]').forEach(button=>button.setAttribute('aria-checked',String(button.dataset.mode===(state.mode||'pilot'))));
  const tied=outcome.leaders.length>1;
  document.querySelector('#winner-letter').textContent=tied?'↗':outcome.winner.toUpperCase();
  document.querySelector('#recommendation-title').textContent=tied?'Resolve the tie, then '+outcome.mode.verb.toLowerCase()+' the leader':outcome.mode.verb+' the '+names[outcome.winner].toLowerCase();
  document.querySelector('#recommendation-reason').textContent=tied?'The vote is tied. Name the assumption that would break it, then run the smallest test.':names[outcome.winner]+' has the strongest team support. '+outcome.mode.detail;
  const note=state.nextStep||'';
  const textarea=document.querySelector('#next-step');
  if(textarea.value!==note)textarea.value=note;
  document.querySelector('#note-count').textContent=note.length+' / 240';
  document.querySelector('#recorded-recommendation').textContent=state.recommendation||outcome.recommendation;
  if(state.recommendation!==outcome.recommendation)window.buildParty.setState('recommendation',outcome.recommendation);
}
document.querySelectorAll('[data-vote]').forEach(button=>button.addEventListener('click',()=>{
  const state=window.buildParty.getState();
  const option=button.dataset.vote;
  const votes={...(state.votes||{}),[option]:(Number((state.votes||{})[option])||0)+1};
  window.buildParty.patchState({votes});
  document.querySelector('#vote-announcement').textContent='Vote added for '+names[option];
}));
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>window.buildParty.setState('mode',button.dataset.mode)));
document.querySelector('#next-step').addEventListener('input',event=>{document.querySelector('#note-count').textContent=event.target.value.length+' / 240';window.buildParty.setState('nextStep',event.target.value)});
document.querySelector('#copy-summary').addEventListener('click',async()=>{
  const state=window.buildParty.getState();
  const outcome=getOutcome(state);
  const summary=(state.recommendation||outcome.recommendation)+': '+(state.nextStep||'Define the first success condition.');
  try{await navigator.clipboard.writeText(summary);document.querySelector('#copy-status').textContent='Copied'}catch{document.querySelector('#copy-status').textContent='Select text'}
});
window.buildParty.subscribe(render);
render(window.buildParty.getState());
